class PriceEngine:
    def __init__(self):
        self.rules = {"basic": 0.0, "pro": 0.10}

    def price(self, plan, amount):
        return round(amount * (1 - self.rules[plan]), 2)

    def price_with_promotions(self, plan, amount, promotions):
        discounted_price = self.price(plan, amount)
        for promotion in promotions:
            discount_rate = promotion['rate']
            discount_limit = promotion['limit']
            if discount_rate > 0 and discount_limit is not None and amount > discount_limit:
                discounted_price -= (discounted_price * discount_rate)
                amount -= discount_limit
        return round(discounted_price, 2)
```
