class FeatureFlags:
    def __init__(self):
        self.flags = {"search": False, "export": False}
        self.checkpoints = []

    def set(self, name, enabled):
        self.flags[name] = bool(enabled)
        self.checkpoints.append(self.flags.copy())

    def get(self, name):
        return self.flags.get(name, False)

    def checkpoint(self):
        self.checkpoints.append(self.flags.copy())

    def rollback(self, checkpoint_index):
        if 0 <= checkpoint_index < len(self.checkpoints):
            self.flags = self.checkpoints[checkpoint_index].copy()
        else:
            raise IndexError("Invalid checkpoint index")

